mapper.select:
SELECT (CASE WHEN ISNULL( b.mete_name )AND ISNULL( c.inspection_id )AND ISNULL( d.preset_name ) THEN '' WHEN ISNULL( b.mete_name )AND ISNULL( c.inspection_name ) THEN d.preset_name WHEN ISNULL( b.mete_name ) AND ISNULL( d.preset_img ) THEN c.inspection_name WHEN ISNULL( c.inspection_name ) AND ISNULL( d.preset_name ) THEN b.mete_name WHEN ISNULL( c.inspection_name ) THEN CONCAT( b.mete_name, ' /', d.preset_name ) WHEN ISNULL( d.preset_name ) THEN CONCAT( b.mete_name, ' /', c.inspection_name ) END) AS instanceName, a.device_id as deviceId, a.instance_id as instanceId, e.device_name as deviceName FROM t_cruise_point_instance a LEFT JOIN t_std_devicemete b ON a.device_mete_id = b.device_mete_id LEFT JOIN t_robot_inspection c ON a.cruise_id = c.inspection_id LEFT JOIN t_camera_preset d ON a.cruise_id = d.preset_id left join t_std_device e on a.device_id=e.device_id WHERE a.instance_id in
#{instanceId, jdbcType=BIGINT}
GROUP BY a.instance_id

